contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address other, uint256 amount) public payable {
        require(other != address(this), "other must differ from test");

        uint256 beforeOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 beforeSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeC = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 afterSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterC = address(c).balance;

        assert(
            afterOther == beforeOther &&
            ((beforeSelf == 0 && !reverted && afterSelf == 0 && afterC == beforeC) ||
             (beforeSelf != 0 && reverted && afterSelf == beforeSelf && afterC == beforeC))
        );
    }
}

